import { defineConfig } from "@rustybuns/cli/config";

// QNTBR on Rusty Buns: one RWSDK Worker, packed three ways from this file.
//
//   pnpm exec rustybuns build desktop --dev && pnpm exec rustybuns run desktop
//   pnpm exec rustybuns plan        # typechecks the stack and lists what it would create; creates nothing
//   pnpm exec rustybuns deploy      # refuses without a plan for this exact config, then asks
//
// Generated by `rustybuns init` from wrangler.jsonc, then tuned by hand:
//  - assets point at the RWSDK client build (dist/client), not the raw public/ folder
//  - the desktop runs the real Worker on Bun with sqlite behind D1, KV, R2 and every
//    Durable Object (mode "worker"), since the app is server-driven (RSC, DOs, Prisma on D1)
//  - every secret the app reads from `env` is declared here by name. Values come from
//    .dev.vars or the shell at build and deploy time and never land in this file.
//
// What stays in wrangler.jsonc for now: the custom-domain routes (qntbr.com/*,
// *.qntbr.com/*) and observability. This CLI version has no field for them, and
// `npm run release` still deploys the live Worker through wrangler as before.
//
// Alchemy names the resources it creates itself (`adopt` is off), so a first
// `plan`/`deploy` from here cannot touch the live Worker, D1 database or buckets.
// When this stack is meant to take over the live resources, set
// `targets.edge.adopt: true` (see @rustybuns/cli/config).

export default defineConfig({
  name: "qntbr",
  worker: {
    main: "src/worker.tsx",
    builtMain: "dist/worker/index.js",
    assets: "dist/client",
    compatibilityDate: "2025-08-21",
    compatibilityFlags: ["nodejs_compat"],
    build: "prisma generate && RWSDK_DEPLOY=1 vite build",
    // OAuth codes and magic-link tokens travel in query strings; keep them out of Workers Logs.
    redactQueryStrings: true,
  },
  bindings: {
    // better-auth tables, orgs, decks, everything Prisma owns. Migrations apply at boot on the desktop.
    DB: { type: "d1", databaseName: "qntbr-db1", migrationsDir: "migrations" },

    GAME_REGISTRY_KV: { type: "kv" },
    CARD_GAME_REGISTRY_KV: { type: "kv" },
    DECKS_KV: { type: "kv" },
    RATELIMIT_KV: { type: "kv" },
    AUTH_CACHE_KV: { type: "kv" },
    CARDS_KV: { type: "kv" },

    // 3D models and other VTT uploads. On the desktop this is a folder in the data dir.
    VTT_ASSETS: { type: "r2", bucketName: "qbear3-vtt-models" },

    // One Durable Object per room/session. In-process with sqlite storage on the desktop.
    SESSION_DURABLE_OBJECT: { type: "durable_object", className: "SessionDurableObject" },
    REALTIME_DURABLE_OBJECT: { type: "durable_object", className: "RealtimeDurableObject" },
    GAME_STATE_DO: { type: "durable_object", className: "GameStateDO" },
    CARD_GAME_STATE_DO: { type: "durable_object", className: "CardGameDO" },
    CARD_CACHE_DO: { type: "durable_object", className: "CardCacheDO" },
    CACHE_WARMING_DO: { type: "durable_object", className: "CacheWarmingDO" },
    SYNCED_STATE_SERVER: { type: "durable_object", className: "SyncedStateServer" },
    DRAFT_DO: { type: "durable_object", className: "DraftDO" },
    USER_SESSION_DO: { type: "durable_object", className: "UserSessionDO" },
    MATCHMAKING_DO: { type: "durable_object", className: "MatchmakingDO" },
    VTT_DO: { type: "durable_object", className: "VTTDO" },

    WEBAUTHN_APP_NAME: { type: "var", value: "qntbr" },
    BETTER_AUTH_URL: { type: "var", value: "https://qntbr.com" },

    // Required: better-auth signs sessions with it (src/lib/auth.ts).
    BETTER_AUTH_SECRET: { type: "secret" },
    // Encrypts stored third-party API keys (src/lib/encrypt.ts).
    API_ENCRYPTION_KEY: { type: "secret" },

    // Optional: each feature is off, or falls back, when its key has no value.
    WEBAUTHN_RP_ID: { type: "secret", optional: true },      // falls back to the request hostname
    WORKER_HOST: { type: "secret", optional: true },         // MatchmakingDO calls back to this host; defaults to qntbr.com
    TURNSTILE_SECRET_KEY: { type: "secret", optional: true },
    RESEND_API_KEY: { type: "secret", optional: true },
    GOOGLE_CLIENT_ID: { type: "secret", optional: true },
    GOOGLE_CLIENT_SECRET: { type: "secret", optional: true },
    DISCORD_CLIENT_ID: { type: "secret", optional: true },
    DISCORD_CLIENT_SECRET: { type: "secret", optional: true },
    DISCORD_BOT_TOKEN: { type: "secret", optional: true },
    DISCORD_GUILD_ID: { type: "secret", optional: true },
    DISCORD_GAME_CHANNEL_ID: { type: "secret", optional: true },
    STRIPE_SECRET_KEY: { type: "secret", optional: true },
    STRIPE_WEBHOOK_SECRET: { type: "secret", optional: true },
    STRIPE_STARTER_PRICE_ID: { type: "secret", optional: true },
    STRIPE_PRO_PRICE_ID: { type: "secret", optional: true },
    LEMON_SQUEEZY_WEBHOOK_SECRET: { type: "secret", optional: true },
    LEMON_SQUEEZY_STARTER_VARIANT_ID: { type: "secret", optional: true },
    LEMON_SQUEEZY_PRO_VARIANT_ID: { type: "secret", optional: true },
    NEXT_PUBLIC_LEMON_SQUEEZY_STARTER_VARIANT_ID: { type: "secret", optional: true },
    NEXT_PUBLIC_LEMON_SQUEEZY_PRO_VARIANT_ID: { type: "secret", optional: true },
    ASANA_PROJECT_GID: { type: "secret", optional: true },
  },
  targets: {
    edge: { provider: "cloudflare" },
    // The desktop app: the same Worker on Bun, data in ~/.qntbr, UI in the user's Chrome.
    // `targets: "all"` cross-compiles macOS, Linux and Windows from one machine (no Rust in this build).
    desktop: { mode: "worker", window: "app", dataDir: "~/.qntbr", targets: ["darwin-arm64"] },
  },
  source: {
    dir: "src",
    aliases: { "@": "src", "@generated": "generated" },
  },
});
